import{_ as e,o,c as a,a0 as r}from"./chunks/framework.DCToIpx6.js";const u=JSON.parse('{"title":"REQ-COL-VISIBILITY — Column Visibility","description":"","frontmatter":{},"headers":[],"relativePath":"tests/test-cases/dynamic-column-config/REQ-COL-VISIBILITY.md","filePath":"tests/test-cases/dynamic-column-config/REQ-COL-VISIBILITY.md"}'),d={name:"tests/test-cases/dynamic-column-config/REQ-COL-VISIBILITY.md"};function n(i,t,s,l,c,b){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="req-col-visibility-—-column-visibility" tabindex="-1">REQ-COL-VISIBILITY — Column Visibility <a class="header-anchor" href="#req-col-visibility-—-column-visibility" aria-label="Permalink to &quot;REQ-COL-VISIBILITY — Column Visibility&quot;">​</a></h1><p><strong>Requerimiento:</strong> La tabla DEBE excluir columnas con <code>visible: false</code> del DOM renderizado. Columnas con <code>visible: undefined</code> o <code>true</code> DEBEN renderizarse normalmente.</p><hr><h2 id="tc-col-visibility-01-columna-con-visible-false-se-excluye-del-dom" tabindex="-1">TC-COL-VISIBILITY-01: Columna con visible: false se excluye del DOM <a class="header-anchor" href="#tc-col-visibility-01-columna-con-visible-false-se-excluye-del-dom" aria-label="Permalink to &quot;TC-COL-VISIBILITY-01: Columna con visible: false se excluye del DOM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-VISIBILITY-01</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-VISIBILITY</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Componente <code>GenericTableWithoutActionsComponent</code> inicializado con columnas: <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}]</code> y al menos una fila de datos</td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla con columnas mixtas (visible y visible:false)<br>2. Renderizar el componente<br>3. Inspeccionar el DOM renderizado</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La columna <code>name</code> aparece en el DOM. La columna <code>secret</code> NO aparece en el DOM (no debe estar ni siquiera con <code>display:none</code>).</td></tr><tr><td><strong>Notas</strong></td><td>Verificar con querySelector que no exista ningún elemento con clave <code>secret</code> en el encabezado ni en las celdas.</td></tr></tbody></table><hr><h2 id="tc-col-visibility-02-columna-con-visible-true-se-renderiza" tabindex="-1">TC-COL-VISIBILITY-02: Columna con visible: true se renderiza <a class="header-anchor" href="#tc-col-visibility-02-columna-con-visible-true-se-renderiza" aria-label="Permalink to &quot;TC-COL-VISIBILITY-02: Columna con visible: true se renderiza&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-VISIBILITY-02</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-VISIBILITY</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Tabla con columna <code>{key: &#39;email&#39;, header: &#39;Email&#39;, visible: true}</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla<br>2. Renderizar<br>3. Verificar DOM</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La columna <code>email</code> se renderiza normalmente en el DOM.</td></tr></tbody></table><hr><h2 id="tc-col-visibility-03-columna-sin-visible-undefined-se-renderiza" tabindex="-1">TC-COL-VISIBILITY-03: Columna sin visible (undefined) se renderiza <a class="header-anchor" href="#tc-col-visibility-03-columna-sin-visible-undefined-se-renderiza" aria-label="Permalink to &quot;TC-COL-VISIBILITY-03: Columna sin visible (undefined) se renderiza&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-VISIBILITY-03</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-VISIBILITY</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (borde)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Tabla con columna <code>{key: &#39;name&#39;, header: &#39;Name&#39;}</code> (sin propiedad <code>visible</code>)</td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla<br>2. Renderizar<br>3. Verificar DOM</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La columna <code>name</code> se renderiza normalmente (comportamiento por defecto).</td></tr></tbody></table><hr><h2 id="tc-col-visibility-04-todas-las-columnas-con-visible-false-—-tabla-vacia" tabindex="-1">TC-COL-VISIBILITY-04: Todas las columnas con visible:false — tabla vacía <a class="header-anchor" href="#tc-col-visibility-04-todas-las-columnas-con-visible-false-—-tabla-vacia" aria-label="Permalink to &quot;TC-COL-VISIBILITY-04: Todas las columnas con visible:false — tabla vacía&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-VISIBILITY-04</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-VISIBILITY</td></tr><tr><td><strong>Prioridad</strong></td><td>Media</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Edge Case</td></tr><tr><td><strong>Precondiciones</strong></td><td>Todas las columnas tienen <code>visible: false</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla solo con columnas ocultas<br>2. Renderizar<br>3. Verificar DOM</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La tabla se renderiza sin columnas visibles (sin headers y sin celdas de datos). Las filas pueden existir en el modelo pero no hay celdas visibles.</td></tr><tr><td><strong>Notas</strong></td><td>Escenario borde: el consumidor debe saber que no tiene columnas visibles.</td></tr></tbody></table>',14)])])}const m=e(d,[["render",n]]);export{u as __pageData,m as default};
